import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, texture, vec2, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'collection-card-3-label';

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const accentColor = new Color(colors.accent);
  const paperColor = new Color(colors.paper);

  // Card dimensions from atlas 512x320 (1.6:1 ratio)
  const cardW = 1.6;
  const cardH = 1.0;

  // --- Textured card plane ---
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    // Fallback engineered gradient (surface -> ink, bottom to top)
    colorNode: mix(
      uniform(surfaceColor),
      uniform(inkColor),
      smoothstep(float(0.0), float(1.0), uv().y)
    ),
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.renderOrder = 0;
  group.add(cardMesh);

  // Load and apply the card image texture
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  const srcW = 512;
  const srcH = 320;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;

      const atlasW = (tex.image && tex.image.width) || srcW;
      const atlasH = (tex.image && tex.image.height) || srcH;

      if (atlasW === srcW && atlasH === srcH) {
        // Texture matches source rect — use directly
        cardMat.colorNode = texture(tex);
      } else {
        // Atlas: remap UVs to source rect (0,0 -> 512,320)
        const u0 = 0;
        const u1 = srcW / atlasW;
        const v0 = 1 - srcH / atlasH;
        const v1 = 1;
        const remappedUV = uv()
          .mul(vec2(u1 - u0, v1 - v0))
          .add(vec2(u0, v0));
        cardMat.colorNode = texture(tex, remappedUV);
      }
      cardMat.needsUpdate = true;
    });
  }

  // --- Accent line (signal red) ---
  const accentGeo = new PlaneGeometry(0.14, 0.016);
  const accentMat = new MeshBasicNodeMaterial({
    color: accentColor,
    transparent: true,
  });
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(-0.58, 0.3, 0.02);
  group.add(accentLine);

  // --- Headline text "Collection 3" ---
  for (const item of items) {
    const fontSizePx = item.typography?.fontSize ?? 39;
    // Convert px to scene units (≈100px per unit, slightly compressed)
    const sceneFontSize = fontSizePx / 130;
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize: sceneFontSize,
      color: colors.paper,
      align: 'center',
    });
    // Position label at lower third of card
    textObj.position.set(0, -0.28, 0.03);
    group.add(textObj);
  }

  // --- Cleanup ---
  const disposables = [cardGeo, cardMat, accentGeo, accentMat];
  group.userData.cleanup = () => {
    for (const d of disposables) {
      try { d.dispose(); } catch (e) { /* noop */ }
    }
  };

  group.userData.handlers = {};

  return group;
}
